function verdict(c){
 if(conflicts(c).length)return 'conflict';
 if(c.incomplete||!state.confirmed||profileRestrictions().unknown.length)return 'unknown';
 return 'match';
}
const matches=()=>capsules.filter(c=>verdict(c)==='match');
