let pointerEdit=null;
$('editor').onpointerdown=e=>{
 if(state.printing||pointerEdit||e.button>0||e.target.closest('[data-edit]'))return;
 const hit=e.target.closest('[data-i]');if(hit&&freeParts[Number(hit.dataset.i)]?.fixedBase)return;
 wkActiveView='top';const pt=editorPoint(e);if(drawing){rememberEdit();activeStroke={points:[[pt.x,pt.y]],color:$('brushColor').value,width:.026};strokes.push(activeStroke);pointerEdit={kind:'draw',id:e.pointerId,committed:true};}
 else{const handle=e.target.closest('[data-handle]'),b=e.target.closest('[data-i]');if(handle&&freeParts[selected]){const before=snapshot();const p=freeParts[selected];pointerEdit={id:e.pointerId,before,kind:handle.dataset.handle,startAngle:Math.atan2(pt.y-p.y,pt.x-p.x),angle:p.angle,distance:Math.max(.05,Math.hypot(pt.x-p.x,pt.y-p.y)),scale:p.s};}
 else if(b){selected=Number(b.dataset.i);const before=snapshot(),p=freeParts[selected];pointerEdit={id:e.pointerId,before,startX:e.clientX,startY:e.clientY,kind:'move',dx:p.x-pt.x,dy:p.y-pt.y};}
 else{selected=-1;paintEditor();return}}
 e.preventDefault();$('editor').setPointerCapture(e.pointerId);paintEditor();
};
$('editor').onpointermove=e=>{if(!pointerEdit||e.pointerId!==pointerEdit.id)return;if(!pointerEdit.committed&&pointerEdit.kind!=='draw'){if(pointerEdit.kind==='move'&&Math.hypot(e.clientX-pointerEdit.startX,e.clientY-pointerEdit.startY)<2)return;rememberEdit(pointerEdit.before);pointerEdit.committed=true;}const pt=editorPoint(e),p=freeParts[selected];
 if(pointerEdit.kind==='draw'){if(activeStroke.points.length<1500){const last=activeStroke.points.at(-1);if(Math.hypot(pt.x-last[0],pt.y-last[1])>.015)activeStroke.points.push([pt.x,pt.y])}}
 else if(!p)return;
 else if(pointerEdit.kind==='move'){p.x=Math.max(-1.25,Math.min(1.25,pt.x+pointerEdit.dx));p.y=Math.max(-.9,Math.min(.9,pt.y+pointerEdit.dy))}
 else if(pointerEdit.kind==='resize')p.s=Math.max(.12,Math.min(.9,pointerEdit.scale*Math.hypot(pt.x-p.x,pt.y-p.y)/pointerEdit.distance));
 else if(pointerEdit.kind==='rotate')p.angle=pointerEdit.angle+Math.atan2(pt.y-p.y,pt.x-p.x)-pointerEdit.startAngle;
 if(p&&!drawing)constrainPart(p);
 paintEditor();draw();
};
function endPointer(e){if(!pointerEdit||e.pointerId!==pointerEdit.id)return;if(activeStroke&&activeStroke.points.length<2)strokes.pop();pointerEdit=null;activeStroke=null;paintEditor();draw()}
$('editor').onpointerup=$('editor').onpointercancel=$('editor').onlostpointercapture=endPointer;
$('editor').onkeydown=e=>{if(e.target.closest('[data-edit],[data-handle]'))return;const b=e.target.closest('[data-i]');if(!b||freeParts[Number(b.dataset.i)]?.fixedBase)return;wkActiveView='top';selected=Number(b.dataset.i);if(['Delete','Backspace'].includes(e.key)){e.preventDefault();editPiece('remove')}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const p=freeParts[selected];rememberEdit();const d=e.shiftKey?.15:.04;if(e.key==='ArrowLeft')p.x-=d;if(e.key==='ArrowRight')p.x+=d;if(e.key==='ArrowUp')p.y-=d;if(e.key==='ArrowDown')p.y+=d;p.x=Math.max(-1.25,Math.min(1.25,p.x));p.y=Math.max(-.9,Math.min(.9,p.y));constrainPart(p);paintEditor();draw();$('editor').querySelector('[data-i="'+selected+'"]')?.focus()}else if(e.key==='Enter'||e.key===' '){e.preventDefault();paintEditor()}};
document.addEventListener('keydown',e=>{if(state.page!=='studio'||wkMode!=='template'||state.printing||e.target.closest('input,textarea,select'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redoEdit():undoEdit()}if(e.key==='Escape'){drawing=false;selected=-1;delete $('viewPair').dataset.expanded;syncBench()}});
// Mouse orbit, vertical tilt, wheel zoom, and two-touch pinch zoom.
const viewPointers=new Map();let viewGesture=null;
scene.onpointerdown=e=>{if(state.printing)return;viewPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});scene.setPointerCapture(e.pointerId);state.spin=false;if(viewPointers.size===1)viewGesture={x:e.clientX,y:e.clientY,a:state.angle,p:viewPitch};else{const [a,b]=[...viewPointers.values()];viewGesture={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:viewZoom}};e.preventDefault()};
scene.onpointermove=e=>{if(!viewPointers.has(e.pointerId)||!viewGesture)return;viewPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(viewPointers.size===1&&viewGesture.a!==undefined){state.angle=viewGesture.a+(e.clientX-viewGesture.x)*.012;viewPitch=Math.max(.15,Math.min(.85,viewGesture.p+(e.clientY-viewGesture.y)*.003))}else if(viewPointers.size>1&&viewGesture.distance){const[a,b]=[...viewPointers.values()];viewZoom=Math.max(.55,Math.min(1.75,viewGesture.zoom*Math.hypot(a.x-b.x,a.y-b.y)/viewGesture.distance))}draw()};
scene.onpointerup=scene.onpointercancel=scene.onlostpointercapture=e=>{viewPointers.delete(e.pointerId);if(viewPointers.size===1){const p=[...viewPointers.values()][0];viewGesture={x:p.x,y:p.y,a:state.angle,p:viewPitch}}else if(!viewPointers.size)viewGesture=null};
scene.addEventListener('wheel',e=>{e.preventDefault();viewZoom=Math.max(.55,Math.min(1.75,viewZoom*Math.exp(-e.deltaY*.0015)));state.spin=false;draw()},{passive:false});
document.querySelector('.marketJump').onclick=e=>{const b=e.target.closest('[data-market]');if(b)setMarket(b.dataset.market)};
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-good],[data-claim],[data-use-good]');
 if(!button)return;
 e.stopImmediatePropagation();
 const g=goods.find(item=>item.id===(button.dataset.good||button.dataset.claim||button.dataset.useGood));
 if(!g||state.printing)return;
 if(button.dataset.claim||!g.price||owned.includes(g.id)){
   claimRecipe(g);
 }else{
   showExchange(g);
 }
},true);
function showExchange(g){
 const balance=points(), enough=balance>=g.price;
 const controls=enough?'<button class="primary" data-claim="'+g.id+'">确认兑换并打开</button>':'';
 modal('<h2>'+escapeHtml(g.name)+'</h2><p>兑换需要 '+g.price+' 体验积分，当前余额 '+balance+' 积分。</p><p>'+
   (enough?'兑换后剩余 '+(balance-g.price)+' 积分，可在此浏览器重复编辑。':'还差 '+(g.price-balance)+' 积分。')+
   '</p><div class="actions">'+controls+'<button class="secondary" data-close>'+(enough?'取消':'返回菜谱')+'</button></div>');
}
async function claimRecipe(g){
 const acquire=()=>{
   if(state.printing)return;
   updateRecipeWallet();
   if(!owned.includes(g.id)){
     if(points()<g.price){showExchange(g);return}
     try{
       localStorage.setItem(recipeReceiptPrefix+g.id,String(g.price));
     }catch{
       toast('浏览器未能保存领取记录，请允许本站使用本机存储后再试。');return;
     }
     updateRecipeWallet();
   }
   useGood(g);
 };
 if(globalThis.navigator?.locks){
   await navigator.locks.request('ankuan-recipe-wallet',acquire);
 }else{acquire()}
}
window.addEventListener('storage',e=>{
 if(e.key===null||e.key===legacyRecipeKey||e.key.startsWith(recipeReceiptPrefix)){
   updateRecipeWallet();renderMarket();
 }
});

// Streamlined studio: a single search/command box and passive material notices.
function isEditCommand(value){return /^(添加|加一个|加一颗|加|放一个|来一个|撤销|重做|后退一步|改|变|换|设|放大|缩小|旋转|转动|逆时针|左移|右移|上移|下移|向左|向右|向上|向下|删除|删掉|移除|上一层|下一层|叠到)/.test(value.trim())}
function runSmartInput(){const value=$('assetSearch').value.trim();if(!value)return;if(isEditCommand(value))executeCommand(value);else{renderAssets();statusMessage('已筛选“'+value+'”。点击素材添加，或输入“添加'+value+'”。')}}
function ingredientConflicts(c){
 const aliases={麸质:/小麦|小麥|面粉|麵粉|麸质|麩質|面筋|麵筋|大麦|黑麦|麦芽/,鸡蛋:/鸡蛋|雞蛋|蛋黄|蛋黃|蛋白|蛋清|全蛋/,牛奶:/牛奶|奶粉|乳清|酪蛋白|奶油|乳制品|乳脂|黄油|黃油/,花生坚果:/花生|坚果|堅果|核桃|杏仁|榛子|腰果|开心果|松子|碧根果|夏威夷果|巴旦木/,大豆:/大豆|黄豆|黃豆|豆乳|豆浆|豆漿|豆腐/,海鲜:/海鲜|海鮮|虾|蝦|蟹|贝|貝|鱼|魚/,番茄:/番茄|西红柿|西紅柿/};
 const ingredients=[...Object.keys(c.tags||{}),...(c.ingredients||[])];
 return state.profile.filter(term=>ingredients.some(item=>(aliases[term]?aliases[term].test(item):item.includes(term))));
}
function selectedMaterialIds(){return state.selectedMaterials||(state.selectedMaterials=state.capsule===null?[]:[state.capsule]);}
function selectedMaterialRecords(){return selectedMaterialIds().map(id=>capsules[id]).filter(Boolean);}
function materialPreviewColor(){const list=selectedMaterialRecords();return list.length===1?list[0].color:'#a8a399';}
function materialsAllowed(){const list=selectedMaterialRecords();return state.confirmed&&list.length>0&&list.every(c=>state.materialApprovals?.[c.id]===c.batch&&verdict(c)==='match');}
function invalidateSimulation(){state.revision++;state.scan++;state.printSeq++;state.printing=false;$('printState').textContent='';}
function clearApproval(){invalidateSimulation();approvedBatch=null;state.materialApprovals={};state.selectedMaterials=[];state.capsule=null;}
function setMaterials(ids,{remember=true}={}){
 const next=[...new Set(ids)].filter(id=>Number.isInteger(id)&&capsules[id]).sort((a,b)=>a-b);
 if(remember&&JSON.stringify(next)!==JSON.stringify(selectedMaterialIds()))rememberEdit();
 const interrupted=state.printing;invalidateSimulation();state.selectedMaterials=next;state.capsule=next[0]??null;state.materialApprovals={};
 next.forEach(id=>{if(state.confirmed&&verdict(capsules[id])==='match')state.materialApprovals[id]=capsules[id].batch;});
 approvedBatch=state.capsule===null?null:state.materialApprovals[state.capsule]??null;
 renderStatus();syncBench();if(interrupted)$('printState').textContent='模拟已停止，材料发生变化。';return allowed();
}
function selectMaterial(id){return setMaterials(id===null?[]:[...selectedMaterialIds(),id]);}
function toggleMaterial(id){return setMaterials(selectedMaterialIds().includes(id)?selectedMaterialIds().filter(x=>x!==id):[...selectedMaterialIds(),id]);}
function scan(id){selectMaterial(Number(id));wkSetMode('template');wkOpenMaterial(true);if(state.page!=='studio')location.hash='studio';dismiss();}
function askProfile(){location.hash='profile';$('familyPanel').open=true;}
function materialMessage(){
 if(!state.confirmed)return {kind:'unknown',title:'请先保存当前档案',detail:''};
 const unknown=profileRestrictions().unknown;if(unknown.length)return {kind:'unknown',title:'忌口信息待确认',detail:unknown.join('、')+'；暂不能模拟打印。'};
 const list=selectedMaterialRecords();if(!list.length)return {kind:'empty',title:'请选择打印材料',detail:''};
 const conflictsList=list.filter(c=>conflicts(c).length);if(conflictsList.length)return {kind:'conflict',title:'所选材料含忌口项',detail:conflictsList.map(c=>c.name+'：'+conflicts(c).join('、')).join('；')};
 const incomplete=list.filter(c=>c.incomplete);if(incomplete.length)return {kind:'unknown',title:'批次资料不完整',detail:incomplete.map(c=>c.name).join('、')+'；请更换材料或批次。'};
 if(!materialsAllowed())return {kind:'unknown',title:'材料批次待确认',detail:'请重新选择材料。'};
 return {kind:'match',title:'',detail:''};
}
function renderMaterialOptions(){
 const box=$('materialOptions');if(!box)return;
 // Build once so a keyboard user retains focus when toggling a checkbox.
 if(!box.querySelector('[data-material]'))box.innerHTML=capsules.map(c=>'<label class="materialOption"><input type="checkbox" data-material="'+c.id+'"><span class="materialSwatch" style="background:'+c.color+'"></span><span><strong class="materialName">'+escapeHtml(c.name)+'</strong><small class="materialIngredients">'+escapeHtml(c.ingredients.join('、'))+'</small><small class="wkBatchLabel"></small><small class="materialRisk"></small></span></label>').join('');
 box.querySelectorAll('[data-material]').forEach(input=>{const c=capsules[Number(input.dataset.material)];input.checked=selectedMaterialIds().includes(c.id);const label=input.closest('.materialOption');label.classList.toggle('selected',input.checked);label.querySelector('.wkBatchLabel').textContent=c.batch;const risk=label.querySelector('.materialRisk');risk.textContent=conflicts(c).length?'含'+conflicts(c).join('、'):c.incomplete?'批次待确认':'';risk.hidden=!risk.textContent;});
}
function refreshShelf(){
 if(!state.confirmed)onlyMatches=false;
 $('allCaps').setAttribute('aria-pressed',String(!onlyMatches));$('matchCaps').setAttribute('aria-pressed',String(onlyMatches));$('matchCaps').disabled=!state.confirmed;
 $('matchCaps').textContent='无已知冲突'+(state.confirmed?' '+matches().length:'');
 for(const card of $('shelf').children){const c=capsules[Number(card.dataset.id)],hit=conflicts(c),v=verdict(c);card.hidden=onlyMatches&&v!=='match';card.querySelector('.lotNumber').textContent=c.batch;const info=card.querySelector('.compat');info.className='compat';
 if(hit.length){info.textContent='含忌口项 · '+hit.join('、');info.classList.add('blocked');}
 else if(!state.confirmed){info.textContent='请完善档案';}
 else if(v==='unknown'){info.textContent='信息待确认';info.classList.add('unknown');}
 else{info.textContent=(selectedMaterialIds().includes(c.id)?'已选择 · ':'')+'无已登记冲突';info.classList.add('ok');}}
}
function renderStatus(){
 refreshShelf();renderMarket();
 if(typeof renderProfileSummary==='function')renderProfileSummary();
 $('matchCount').textContent=state.confirmed?matches().length+' / 5':'— / 5';
 $('recommend').innerHTML=state.confirmed&&matches().length?'<div class="picks">'+matches().map(c=>'<button data-scan="'+c.id+'" aria-label="选择材料'+c.name+'"><i style="background:'+c.color+'"></i>'+c.name+' ↗</button>').join('')+'</div>':'<p class="quiet">请先完善档案中的待确认信息，再查看示例材料。</p>';
 const good=allowed(),list=selectedMaterialRecords();
 $('deviceText').textContent=list.length?list.map(c=>c.name).join(' + '):'未选择材料';
 document.querySelector('.device').classList.toggle('ready',good);
 $('flavor').value=state.capsule===null?'':String(state.capsule);$('flavor').hidden=true;
 $('activeProfileLink').textContent='档案 · '+profileDisplayName()+' ↗';
 const notice=materialMessage();$('materialNotice').hidden=notice.kind==='match';$('materialNotice').className='materialNotice '+notice.kind;$('materialNotice').innerHTML=notice.title?'<strong>'+escapeHtml(notice.title)+'</strong>'+(notice.detail?'<p>'+escapeHtml(notice.detail)+'</p>':''):'';
 $('loaded').innerHTML='<div class="status"><span>'+escapeHtml(list.map(c=>c.name).join(' + ')||'未选择材料')+'</span><a href="#studio">选择材料 ↗</a></div>';
 if($('gate')){$('gate').textContent='';$('gate').hidden=true;}if($('benchBatch')){$('benchBatch').textContent='';$('benchBatch').hidden=true;}
 $('printBtn').textContent=state.printing?'模拟进行中…':'模拟打印 →';$('printBtn').disabled=state.printing||state.analyzing||!currentPieces().length||!good;
 $('printBtn').title=good?'模拟打印':notice.title;
 $('workspace').inert=state.printing;$('editor').style.setProperty('--part-color',materialPreviewColor());
 if($('materialPreviewLabel'))$('materialPreviewLabel').textContent=list.length>1?'多材料 · 中性示意色':'';
 renderMaterialOptions();
 if(typeof renderPrintReadiness==='function')renderPrintReadiness();
}
// Batch approval is recorded independently for every selected material.
$('lotPicker').onchange=e=>{const ids=[...selectedMaterialIds()],interrupted=state.printing;Object.assign(capsules[4],darkLots[Number(e.target.value)],{incomplete:darkLots[Number(e.target.value)].incomplete});renderTrace();setMaterials(ids,{remember:false});if(interrupted)$('printState').textContent='模拟已停止，材料批次发生变化。';};
$('flavor').innerHTML='<option value="">请选择材料</option>'+capsules.map(c=>'<option value="'+c.id+'">'+c.name+'</option>').join('');
$('flavor').onchange=e=>selectMaterial(e.target.value===''?null:Number(e.target.value));
if($('materialOptions'))$('materialOptions').onchange=e=>{const input=e.target.closest('[data-material]');if(input)toggleMaterial(Number(input.dataset.material));};
$('jumpCanvas').onclick=()=>document.querySelector('.benchMain').scrollIntoView({block:'start',behavior:'smooth'});
$('printBtn').onclick=async()=>{
 if(state.printing||state.analyzing||!currentPieces().length)return;
 if(!allowed()){renderStatus();$('materialOptions')?.querySelector('input')?.focus();return;}
 const token=++state.printSeq,rev=state.revision;state.printing=true;workview='model';syncBench();renderStatus();
 for(let l=1;l<=12;l++){
  if(token!==state.printSeq||rev!==state.revision||!allowed()){if(token===state.printSeq){state.printing=false;syncBench();renderStatus();$('printState').textContent='模拟已停止，材料或档案发生变化。';}return;}
  state.layer=l;state.wire=false;draw();$('printState').innerHTML='<p>模拟打印中 · '+Math.round(l/12*100)+'%</p><div class="progress"><i style="width:'+Math.round(l/12*100)+'%"></i></div>';await wait(120);
 }
 if(token!==state.printSeq||rev!==state.revision||!allowed()){if(token===state.printSeq){state.printing=false;syncBench();renderStatus();}return;}
 state.printing=false;syncBench();renderStatus();$('printState').textContent='模拟打印完成 · 仅为过程演示';
};

/* Saved profiles and edit controls are separate. No network requests or report uploads. */
const archiveStorageKey='ankuan.personal.archive.v2';
const profileFieldsV2={name:'profileName',age:'profileAge',gender:'profileGender',severe:'profileSevere',mild:'profileMild',other:'profileOther',likes:'profileLikes',flavor:'profileFlavor',texture:'profileTexture',notes:'profileNotes'};
const fictionalProfileV2={id:'sample-xiaozhi',name:'小知',age:'6',gender:'男孩',severe:'小麦、鸡蛋黄',mild:'番茄',other:'无其他忌口',likes:'米饭、南瓜、草莓',flavor:'清淡、微甜，不辣',texture:'柔软、小口易咀嚼',notes:'新食材先与照护人确认。',fictional:true,saved:true};
let archiveProfilesV2=[{...fictionalProfileV2}],activeProfileIdV2='sample-xiaozhi',archiveReadyV2=false,archiveDirtyV2=false,archiveRememberV2=false,archiveEditingV2=false,archiveNewV2=null;
// Materials belong to the work, not to the profile edit transaction.
let profileMaterialsSnapshotV2=null;
function profileMaterialsV2(){return typeof selectedMaterialIds==='function'?[...selectedMaterialIds()]:[]}
function captureProfileMaterialsV2(){if(profileMaterialsSnapshotV2===null)profileMaterialsSnapshotV2=profileMaterialsV2()}
function restoreProfileMaterialsV2(ids){if(typeof setMaterials==='function')setMaterials(ids,{remember:false})}
function finishProfileMaterialsV2(){const ids=profileMaterialsSnapshotV2??profileMaterialsV2();profileMaterialsSnapshotV2=null;restoreProfileMaterialsV2(ids)}
function warnProfileNavigationV2(){ $('saveNote').textContent='请先保存或取消修改，再离开档案。';$('resetProfileEdit').focus(); }
function guardProfileNavigationV2(event){
 if(!archiveEditingV2)return;
 const link=event.target.closest?.('a[href]');if(!link)return;
 const href=link.getAttribute('href');if(!href?.startsWith('#')||href==='#profile')return;
 event.preventDefault();event.stopImmediatePropagation();warnProfileNavigationV2();
}
function guardProfileHashV2(){
 if(!archiveEditingV2||location.hash==='#profile')return;
 // Replace the rejected history entry, rather than adding another back/forward loop.
 if(typeof history!=='undefined'&&history.replaceState)history.replaceState(null,'','#profile');
 else location.hash='#profile';
 if(typeof updateRoute==='function')updateRoute();warnProfileNavigationV2();
}
const allergyAliasesV2={'小麦':['麸质'],'小麦粉':['麸质'],'面粉':['麸质'],'麸质':['麸质'],'麵筋':['麸质'],'面筋':['麸质'],'鸡蛋黄':['鸡蛋'],'蛋黄':['鸡蛋'],'鸡蛋白':['鸡蛋'],'蛋白':['鸡蛋'],'鸡蛋':['鸡蛋'],'鸡蛋清':['鸡蛋'],'蛋清':['鸡蛋'],'牛奶':['牛奶'],'乳制品':['牛奶'],'花生':['花生坚果'],'坚果':['花生坚果'],'花生坚果':['花生坚果'],'大豆':['大豆'],'黄豆':['大豆'],'海鲜':['海鲜'],'虾':['海鲜'],'蟹':['海鲜'],'番茄':['番茄'],'西红柿':['番茄'],'草莓':['草莓'],'苹果':['苹果'],'可可':['可可'],'芝麻':['芝麻']};
function currentProfileV2(){return archiveProfilesV2.find(p=>p.id===activeProfileIdV2)||archiveProfilesV2[0]}
function profileDisplayName(){return currentProfileV2().name||'未命名档案'}
function parseAllergyTextV2(value){return [...new Set(String(value||'').split(/[、，,;；\n\r\/]+/).map(v=>v.trim()).filter(Boolean))]}
function profileRestrictions(profile=currentProfileV2()){
 const severe=parseAllergyTextV2(profile.severe),mild=parseAllergyTextV2(profile.mild),other=parseAllergyTextV2(profile.other??'无其他忌口'),entries=[];
 for(const [severity,items] of [['severe',severe],['mild',mild],['other',other]])for(const raw of items){
  if((severity!=='other'&&raw==='无已知过敏')||(severity==='other'&&raw==='无其他忌口'))continue;
  const recognized=Object.hasOwn(allergyAliasesV2,raw),terms=recognized?allergyAliasesV2[raw]:[raw];entries.push({raw,severity,terms,recognized});
 }
 const unknown=entries.filter(e=>!e.recognized).map(e=>e.raw);
 if(!severe.length&&!mild.length)unknown.push('过敏信息未填写');
 if(!other.length)unknown.push('其他忌口未填写');
 return {terms:[...new Set(entries.flatMap(e=>e.terms))],unknown:[...new Set(unknown)],entries,severe,mild,other};
}
function readProfileDraftV2(){const p={...currentProfileV2()};for(const [key,id] of Object.entries(profileFieldsV2))p[key]=$(id).value.trim();return p}
function applyProfileV2(){const p=currentProfileV2();state.profile=profileRestrictions(p).terms;state.confirmed=Boolean(p.saved)&&!archiveDirtyV2&&!archiveEditingV2}
function renderProfileSummary(){
 if(!archiveReadyV2)return;
 const p=currentProfileV2();$('profileDisplayName').textContent=p.name||'新档案';$('profileAvatar').textContent=(p.name||'新').slice(-1);
 $('profileFictional').hidden=!p.fictional;$('profileMeta').textContent=[p.age!==''?p.age+' 岁':null,p.gender!=='未填写'?p.gender:null].filter(Boolean).join(' · ')||'基本信息未填写';
 $('profileActive').textContent=archiveEditingV2?'编辑中 · 尚未应用':p.saved?'当前使用':'待完善';
 $('profileTotal').textContent=String(archiveProfilesV2.length).padStart(2,'0');
 $('profileList').innerHTML=archiveProfilesV2.map(item=>'<button type="button" data-profile-id="'+escapeHtml(item.id)+'" aria-pressed="'+(item.id===activeProfileIdV2)+'"><span class="profileMiniAvatar" aria-hidden="true">'+escapeHtml((item.name||'新').slice(-1))+'</span><span><b>'+escapeHtml(item.name||'新档案')+'</b><small>'+(item.fictional?'虚构示例':item.saved?'个人档案':'尚未保存')+'</small></span></button>').join('');
 for(const key of ['severe','mild','other','likes','flavor','texture','notes'])$('view'+key[0].toUpperCase()+key.slice(1)).textContent=p[key]||'未填写';
 $('profileReadView').hidden=archiveEditingV2;$('profileForm').hidden=!archiveEditingV2;$('editProfile').hidden=archiveEditingV2;
 $('profileEditTitle').textContent=archiveNewV2?'新建档案':'编辑档案';
 $('profileStorageState').textContent=archiveRememberV2?'已在此浏览器保存。':'仅保留在当前页面。';
 renderProfileMappingV2(archiveEditingV2?readProfileDraftV2():p);
}
function renderProfileMappingV2(profile){const r=profileRestrictions(profile);$('profileMapping').textContent=r.unknown.length?'待核对：'+r.unknown.join('、')+'。模拟打印已拦截。':'过敏与忌口均参与比对；实际食用前仍需核对配料与交叉接触。'}
function fillProfileFormV2(){const p=currentProfileV2();for(const [key,id] of Object.entries(profileFieldsV2))$(id).value=p[key]??'';$('remember').checked=archiveRememberV2;archiveDirtyV2=false;applyProfileV2();renderProfileSummary()}
function beginProfileEditV2(){if(archiveEditingV2)return;captureProfileMaterialsV2();archiveEditingV2=true;clearApproval();fillProfileFormV2();$('saveNote').textContent='';renderStatus();$('profileName').focus()}
function markProfileDirtyV2(){captureProfileMaterialsV2();archiveEditingV2=true;if(!archiveDirtyV2){clearApproval();archiveDirtyV2=true;state.confirmed=false;renderStatus()}$('saveNote').textContent='';renderProfileSummary()}
function persistProfilesV2(){
 try{if(archiveRememberV2){localStorage.setItem(archiveStorageKey,JSON.stringify({version:2,remember:true,active:activeProfileIdV2,profiles:archiveProfilesV2}));$('saveNote').textContent='已保存到此浏览器。'}else{localStorage.removeItem(archiveStorageKey);$('saveNote').textContent='已保存，仅在当前页面保留。'}return true}
 catch{archiveRememberV2=false;$('remember').checked=false;$('saveNote').textContent='已在当前页面应用，但浏览器存储操作失败。请在浏览器设置中检查或清除旧副本。';return false}
}
function saveProfileV2(){
 if(!$('profileForm').reportValidity())return false;
 const p=readProfileDraftV2();if(!p.name){$('profileName').focus();$('saveNote').textContent='请填写档案称呼。';return false}
 captureProfileMaterialsV2();clearApproval();p.saved=true;
 // Editing a fictional example must never silently turn it into a real child's record.
 archiveProfilesV2=archiveProfilesV2.map(item=>item.id===p.id?p:item);archiveDirtyV2=false;archiveEditingV2=false;archiveNewV2=null;archiveRememberV2=$('remember').checked;applyProfileV2();finishProfileMaterialsV2();persistProfilesV2();renderProfileSummary();renderStatus();$('editProfile').focus();return true;
}
function cancelProfileEditV2(){
 if(archiveNewV2){archiveProfilesV2=archiveProfilesV2.filter(p=>p.id!==activeProfileIdV2);activeProfileIdV2=archiveNewV2;archiveNewV2=null}
 archiveEditingV2=false;clearApproval();fillProfileFormV2();finishProfileMaterialsV2();$('saveNote').textContent='已取消修改。';renderStatus();$('editProfile').focus();
}
function initializeProfilesV2(){
 if(archiveReadyV2)return;
 try{const saved=JSON.parse(localStorage.getItem(archiveStorageKey));if(saved?.version===2&&saved.remember===true&&Array.isArray(saved.profiles)&&saved.profiles.length&&saved.profiles.length<=20){
 const profiles=saved.profiles.map(p=>p&&({...p,other:p.other??'无其他忌口'}));
 const valid=profiles.every(p=>p&&typeof p.id==='string'&&p.id.length<100&&Object.keys(profileFieldsV2).every(k=>typeof p[k]==='string'&&p[k].length<=500)&&typeof p.saved==='boolean'&&typeof p.fictional==='boolean');
 if(valid&&new Set(profiles.map(p=>p.id)).size===profiles.length){archiveProfilesV2=profiles;activeProfileIdV2=profiles.some(p=>p.id===saved.active)?saved.active:profiles[0].id;archiveRememberV2=true}
 }}catch{}
 archiveReadyV2=true;fillProfileFormV2();
 document.addEventListener?.('click',guardProfileNavigationV2,true);
 if(typeof window!=='undefined')window.addEventListener('hashchange',guardProfileHashV2);
 $('profileForm').addEventListener('submit',e=>{e.preventDefault();saveProfileV2()});
 $('editProfile').onclick=beginProfileEditV2;
 for(const id of Object.values(profileFieldsV2))$(id).addEventListener('input',markProfileDirtyV2);
 // The storage preference is transactional too: Cancel never writes or deletes saved records.
 $('remember').onchange=markProfileDirtyV2;
 $('resetProfileEdit').onclick=cancelProfileEditV2;
 $('profileList').onclick=e=>{const b=e.target.closest('[data-profile-id]');if(!b||b.dataset.profileId===activeProfileIdV2)return;if(archiveEditingV2){$('saveNote').textContent='请先保存或取消，再切换档案。';return}if(!archiveProfilesV2.some(p=>p.id===b.dataset.profileId))return;const materials=profileMaterialsV2();clearApproval();activeProfileIdV2=b.dataset.profileId;fillProfileFormV2();restoreProfileMaterialsV2(materials);if(archiveRememberV2)persistProfilesV2();else $('saveNote').textContent='';renderStatus()};
 $('addProfile').onclick=()=>{if(archiveEditingV2){$('saveNote').textContent='请先保存或取消，再新建档案。';return}if(archiveProfilesV2.length>=20){$('saveNote').textContent='最多支持 20 份档案。';return}captureProfileMaterialsV2();clearApproval();const p={...fictionalProfileV2,id:'profile-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),fictional:false,saved:false};for(const key of Object.keys(profileFieldsV2))p[key]='';p.gender='未填写';archiveNewV2=activeProfileIdV2;archiveProfilesV2.push(p);activeProfileIdV2=p.id;archiveEditingV2=true;fillProfileFormV2();$('saveNote').textContent='';$('profileName').focus();renderStatus()};
 $('clearProfileStorage').onclick=()=>{try{localStorage.removeItem(archiveStorageKey);localStorage.removeItem('ankuan.family.v1');archiveRememberV2=false;$('remember').checked=false;$('saveNote').textContent='已清除本机副本，当前页面仍保留。';renderProfileSummary()}catch{$('saveNote').textContent='清除失败，请在浏览器设置中清除此站点数据。'}};
 document.querySelectorAll('nav a[href="#profile"]').forEach(a=>a.textContent='个人档案库');
}

// UI affordances only. Material safety remains in the workflow module.
function compactWorkspace(){return matchMedia('(max-width:650px), (min-width:901px) and (max-width:1100px)').matches}
function setCompactView(view){
 const pair=$('viewPair');pair.dataset.compactView=view;delete pair.dataset.expanded;
 document.querySelectorAll('[data-view]').forEach(button=>{const active=button.dataset.view===view;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});
 document.querySelectorAll('[data-expand]').forEach(button=>button.setAttribute('aria-expanded','false'));
 requestAnimationFrame(()=>{paintEditor();draw()});
}
document.querySelectorAll('[data-view]').forEach(button=>{
 button.onclick=()=>setCompactView(button.dataset.view);
 button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const view=e.key==='Home'?'perspective':e.key==='End'?'top':button.dataset.view==='top'?'perspective':'top';setCompactView(view);document.querySelector('[data-view="'+view+'"]').focus()};
});
function goToTools(id='materialPicker'){
 const target=$(id),scroll=document.querySelector('.toolScroll');if(!target)return;
 if(matchMedia('(min-width:901px)').matches){scroll.scrollTo({top:target.offsetTop-scroll.offsetTop-20,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})}
 else target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});
 target.setAttribute('tabindex','-1');target.focus({preventScroll:true});
}
document.querySelectorAll('[data-tool-section]').forEach(button=>button.onclick=()=>goToTools(button.dataset.toolSection));
$('jumpCanvas').onclick=()=>goToTools('commandForm');
$('returnCanvas').onclick=()=>{const panel=document.querySelector('.benchMain');panel.scrollIntoView({block:'start',behavior:'smooth'});panel.focus({preventScroll:true})};
$('readinessAction').onclick=()=>{if(!state.confirmed||profileRestrictions().unknown.length)location.hash='profile';else if(!currentPieces().length)goToTools('freetools');else goToTools('materialPicker')};
const auditResizeObserver=new ResizeObserver(()=>{requestAnimationFrame(paintEditor)});auditResizeObserver.observe($('editor'));
// Changing screen size must not leave a previously expanded, now-hidden view behind.
const auditCompactQuery=matchMedia('(max-width:650px), (min-width:901px) and (max-width:1100px)');auditCompactQuery.addEventListener?.('change',()=>setCompactView($('viewPair').dataset.compactView||'perspective'));
