    for(let y=0;y<sketch.height;y++)for(let x=0;x<sketch.width;x++)if(src[(y*sketch.width+x)*4]<200){x0=Math.min(x,x0);x1=Math.max(x,x1);y0=Math.min(y,y0);y1=Math.max(y,y1);}
